// Generated by `just generate` from `src/plugins/claudetto/slices/advise/domain/context.ts`. Edit the source and run `just generate`.
// The context of one call: the question, the plan, the failing checks, and the end of the conversation, within a byte bound.
// The goal state is read from `.claudetto/goal.json`, and this file knows only the fields that it needs.

import type { SessionMessage } from "claude-code";

/** The part of a goal state that the context reads. */
export type GoalState = {
  readonly steps: readonly {
    readonly title: string;
    readonly checks: readonly unknown[];
  }[];
  readonly step: number;
  readonly results: readonly {
    readonly pass: boolean;
    readonly output: string;
  }[];
};

/** The goal in `text`, or `undefined` when `text` is not a goal. */
export const readGoal = (text: string | null): GoalState | undefined => {
  try {
    const goal = JSON.parse(text ?? "null") as GoalState | null;
    return goal && Array.isArray(goal.steps) ? goal : undefined;
  } catch {
    return undefined;
  }
};

/** The steps of the goal, one line each, with `>` at the current step. */
export const planOf = (goal: GoalState | undefined): string =>
  (goal?.steps ?? [])
    .map((s, i) => `${i === goal?.step ? ">" : "-"} ${i + 1}. ${s.title}`)
    .join("\n");

/** The output of each failing check of the current step. */
export const failingOf = (goal: GoalState | undefined): string =>
  (goal?.results ?? [])
    .map((r, i) => (r.pass ? "" : `Check ${i + 1}: ${r.output.trim()}`))
    .filter(Boolean)
    .join("\n");

const bytes = (text: string) => new TextEncoder().encode(text).length;

const lineOf = (m: SessionMessage): string => {
  const tools = m.toolUses.map((t) => `[${t.tool}]`).join(" ");
  return `${m.role}: ${[m.text, tools].filter(Boolean).join(" ")}`;
};

/** The newest lines of the conversation that fit in `room` bytes. The oldest kept line is cut at its start when it is too long. */
export const tailOf = (
  messages: readonly SessionMessage[],
  room: number,
): string => {
  const kept: string[] = [];
  let left = room;
  for (const m of [...messages].reverse()) {
    if (!m.text && m.toolUses.length === 0) continue;
    const line = lineOf(m);
    const size = bytes(line) + 1;
    if (size > left) {
      if (kept.length === 0 && left > 0) kept.push(line.slice(-left));
      break;
    }
    kept.unshift(line);
    left -= size;
  }
  return kept.join("\n");
};

/** The two parts of the prompt: the plan, which stays the same between calls, and the rest. Both fit in `limit` bytes. */
export const cutContext = (input: {
  readonly question: string;
  readonly messages: readonly SessionMessage[];
  readonly goal: GoalState | undefined;
  readonly limit: number;
}): { plan: string; failing: string; tail: string; question: string } => {
  const question = input.question.trim().slice(0, input.limit);
  const fixed = {
    plan: planOf(input.goal),
    failing: failingOf(input.goal),
    question,
  };
  const used = bytes(fixed.plan + fixed.failing + question);
  return { ...fixed, tail: tailOf(input.messages, input.limit - used) };
};
